<script setup>
import { computed, onMounted, ref, watch } from 'vue';import { Plus, Trophy, Layers3, Users, Swords } from '@lucide/vue'
import { api } from '../../services/api';import { authStore } from '../../stores/auth';import { uiStore } from '../../stores/ui';import { money, date } from '../../utils'
import PageHeader from '../../components/PageHeader.vue';import LoadingBlock from '../../components/LoadingBlock.vue';import EmptyState from '../../components/EmptyState.vue';import EntityAvatar from '../../components/EntityAvatar.vue';import StatusBadge from '../../components/StatusBadge.vue';import BaseModal from '../../components/BaseModal.vue';import PaginationBar from '../../components/PaginationBar.vue'
const isAdmin=computed(()=>authStore.isAdmin.value),loading=ref(true),rows=ref([]),series=ref([]),seasons=ref([]),meta=ref({page:1,limit:18,total:0}),filters=ref({season_id:'',status:'',format_type:''}),modal=ref(''),busy=ref(false),form=ref({})
function resetCompetition(){form.value={competition_mode:'CLUB',series_id:'',season_id:'',name:'',logo_url:'',format_type:'GROUP_AND_KNOCKOUT',coefficient:'1.000',entry_fee:'0',status:'DRAFT',group_count:4,teams_per_group:4,advance_per_group:2,best_third_count:0,group_leg_mode:'ONE_LEG',knockout_size:8,third_place_mode:'SHARED_BRONZE',starts_on:'',ends_on:'',draw_mode:'POTS',pairing_mode:'SEEDED_CONSTRAINED',visual_theme:'COSMIC_GOLD',gold_prize_amount:'0',silver_prize_amount:'0',bronze_prize_amount:'0',champion_upset_points:'25',runnerup_upset_points:'15'}}
function resetSeries(){form.value={code:'',name:'',description:''}}
async function load(page=1){loading.value=true;try{const r=await api.get('/competitions',{page,limit:18,...filters.value});rows.value=r.data;meta.value=r.meta}catch(e){uiStore.notify(e.message,'error')}finally{loading.value=false}}
watch(filters,()=>load(1),{deep:true});onMounted(async()=>{try{const [ser,sea]=await Promise.all([api.get('/competition-series'),api.get('/seasons')]);series.value=ser.data;seasons.value=sea.data}catch{}load()})
function openCompetition(){resetCompetition();modal.value='competition'}function openSeries(){resetSeries();modal.value='series'}
async function createCompetition(){busy.value=true;try{const endpoint=form.value.competition_mode==='WORLD_CUP_48'?'/competitions/world-cup-48':'/competitions';await api.post(endpoint,form.value);uiStore.notify(form.value.competition_mode==='WORLD_CUP_48'?'Đã tạo World Cup 48 quốc gia.':'Đã tạo giải đấu.');modal.value='';load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function createSeries(){busy.value=true;try{const r=await api.post('/competition-series',form.value);series.value.push(r.data);uiStore.notify('Đã tạo hệ giải.');modal.value=''}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
</script>
<template><div><PageHeader eyebrow="Competition Operations" title="Trung tâm giải đấu" description="Tạo giải linh hoạt: vòng bảng, loại trực tiếp, nhánh 2–128 đội, hệ số, phí tham dự và tiền thưởng."><button v-if="isAdmin" class="btn" @click="openSeries"><Layers3 :size="17"/>Tạo hệ giải</button><button v-if="isAdmin" class="btn btn-primary" @click="openCompetition"><Plus :size="17"/>Tạo giải</button></PageHeader><div class="glass card filters"><select v-model="filters.season_id" class="select"><option value="">Tất cả mùa</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select><select v-model="filters.status" class="select"><option value="">Tất cả trạng thái</option><option value="DRAFT">Bản nháp</option><option value="REGISTRATION">Đăng ký</option><option value="GROUP_STAGE">Vòng bảng</option><option value="KNOCKOUT_STAGE">Loại trực tiếp</option><option value="COMPLETED_PENDING_CLOSE">Chờ chốt</option><option value="FINISHED">Đã kết thúc</option></select><select v-model="filters.format_type" class="select"><option value="">Tất cả thể thức</option><option value="GROUP_ONLY">Chỉ vòng bảng</option><option value="KNOCKOUT_ONLY">Chỉ nhánh đấu</option><option value="GROUP_AND_KNOCKOUT">Vòng bảng + nhánh</option></select></div><LoadingBlock v-if="loading"/><EmptyState v-else-if="!rows.length"/><div v-else class="grid-3"><RouterLink v-for="item in rows" :key="item.id" :to="`/portal/competitions/${item.id}`" class="glass card card-hover competition-card" :class="{'world-cup-card':item.competition_mode==='WORLD_CUP_48'}"><div class="top"><EntityAvatar :src="item.logo_url" :name="item.name" :size="56"/><StatusBadge :status="item.status"/></div><span class="eyebrow">{{ item.competition_mode==='WORLD_CUP_48'?'✦ WORLD CUP 48':item.series_name }}</span><h3>{{ item.name }}</h3><p>{{ item.season_name }}</p><div class="metrics"><span><Users :size="15"/>{{ item.approved_teams }} đội</span><span><Swords :size="15"/>{{ item.finished_matches }}/{{ item.match_count }} trận</span><span><Trophy :size="15"/>Hệ số {{ item.coefficient }}</span></div><div class="bottom"><span>{{ date(item.starts_on) }}</span><b>{{ money(item.entry_fee,true) }} phí</b></div></RouterLink></div><PaginationBar v-if="!loading" v-bind="meta" @change="load"/><BaseModal :open="modal==='series'" title="Tạo hệ giải" @close="modal=''" width="560px"><form class="form-grid" @submit.prevent="createSeries"><label><span class="label">Mã hệ giải</span><input v-model="form.code" class="input" required placeholder="C1"/></label><label><span class="label">Tên hệ giải</span><input v-model="form.name" class="input" required placeholder="Champions League"/></label><label class="form-group full"><span class="label">Mô tả</span><textarea v-model="form.description" class="textarea"/></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Tạo hệ giải</button></div></form></BaseModal><BaseModal :open="modal==='competition'" title="Tạo giải đấu" @close="modal=''" width="900px"><form class="form-grid" @submit.prevent="createCompetition"><label class="form-group full"><span class="label">Chế độ giải đấu</span><select v-model="form.competition_mode" class="select"><option value="CLUB">Giải CLB thông thường</option><option value="WORLD_CUP_48">World Cup đặc biệt · 48 quốc gia</option></select></label><div v-if="form.competition_mode==='WORLD_CUP_48'" class="form-group full world-cup-preset"><b>✦ World Cup 48 Preset</b><span>Hệ thống cố định 12 bảng × 4 quốc gia, lấy 24 đội nhất/nhì và 8 hạng ba tốt nhất vào vòng 32.</span></div><label><span class="label">Hệ giải</span><select v-model="form.series_id" class="select" required><option value="">Chọn hệ giải</option><option v-for="s in series" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label><span class="label">Mùa giải</span><select v-model="form.season_id" class="select" required><option value="">Chọn mùa</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label class="form-group full"><span class="label">Tên giải</span><input v-model="form.name" class="input" required/></label><label class="form-group full"><span class="label">URL logo</span><input v-model="form.logo_url" class="input"/></label><label v-if="form.competition_mode==='CLUB'"><span class="label">Thể thức</span><select v-model="form.format_type" class="select"><option value="GROUP_ONLY">Chỉ vòng bảng</option><option value="KNOCKOUT_ONLY">Chỉ loại trực tiếp</option><option value="GROUP_AND_KNOCKOUT">Vòng bảng + nhánh</option></select></label><label v-if="form.competition_mode==='CLUB'"><span class="label">Trạng thái ban đầu</span><select v-model="form.status" class="select"><option value="DRAFT">Bản nháp</option><option value="REGISTRATION">Mở đăng ký</option></select></label><label><span class="label">Hệ số giải</span><input v-model="form.coefficient" type="number" min="0.001" step="0.001" class="input"/></label><label v-if="form.competition_mode==='CLUB'"><span class="label">Phí tham dự</span><input v-model="form.entry_fee" type="number" min="0" class="input"/></label><template v-if="form.competition_mode==='CLUB'&&form.format_type!=='KNOCKOUT_ONLY'"><label><span class="label">Số bảng</span><input v-model.number="form.group_count" type="number" min="0" max="128" class="input"/></label><label><span class="label">Đội mỗi bảng</span><input v-model.number="form.teams_per_group" type="number" min="0" max="128" class="input"/></label><label><span class="label">Đội đi tiếp/bảng</span><input v-model.number="form.advance_per_group" type="number" min="0" max="128" class="input"/></label><label><span class="label">Hạng ba tốt nhất</span><input v-model.number="form.best_third_count" type="number" min="0" max="128" class="input"/></label><label><span class="label">Lượt vòng bảng</span><select v-model="form.group_leg_mode" class="select"><option value="ONE_LEG">Một lượt</option><option value="TWO_LEG">Hai lượt</option></select></label></template><label v-if="form.competition_mode==='CLUB'&&form.format_type!=='GROUP_ONLY'"><span class="label">Kích thước nhánh</span><select v-model.number="form.knockout_size" class="select"><option v-for="n in [2,4,8,16,32,64,128]" :key="n" :value="n">{{ n }} đội</option></select></label><label v-if="form.competition_mode==='CLUB'&&form.format_type!=='GROUP_ONLY'"><span class="label">Hạng ba</span><select v-model="form.third_place_mode" class="select"><option value="SHARED_BRONZE">Đồng hạng ba</option><option value="PLAYOFF">Tranh hạng ba</option><option value="NONE">Không có</option></select></label><template v-if="form.competition_mode==='WORLD_CUP_48'"><label><span class="label">Bốc thăm vòng bảng</span><select v-model="form.draw_mode" class="select"><option value="POTS">4 nhóm hạt giống</option><option value="FULL_RANDOM">Ngẫu nhiên hoàn toàn</option></select></label><label><span class="label">Ghép vòng 32</span><select v-model="form.pairing_mode" class="select"><option value="SEEDED_CONSTRAINED">Hạt giống + tránh cùng bảng</option><option value="FULL_RANDOM">Ngẫu nhiên + tránh cùng bảng</option></select></label><label><span class="label">Giao diện đặc biệt</span><select v-model="form.visual_theme" class="select"><option value="COSMIC_GOLD">Vũ trụ ánh vàng</option><option value="AURORA_BLUE">Cực quang xanh</option><option value="ROYAL_PURPLE">Hoàng gia tím</option></select></label><label><span class="label">Điểm hạ ĐKVĐ</span><input v-model="form.champion_upset_points" type="number" min="0" class="input"/></label><label><span class="label">Thưởng HCV</span><input v-model="form.gold_prize_amount" type="number" min="0" class="input"/></label><label><span class="label">Thưởng HCB</span><input v-model="form.silver_prize_amount" type="number" min="0" class="input"/></label><label><span class="label">Thưởng HCĐ</span><input v-model="form.bronze_prize_amount" type="number" min="0" class="input"/></label><label><span class="label">Điểm hạ á quân</span><input v-model="form.runnerup_upset_points" type="number" min="0" class="input"/></label></template><label><span class="label">Ngày bắt đầu</span><input v-model="form.starts_on" type="date" class="input"/></label><label><span class="label">Ngày kết thúc</span><input v-model="form.ends_on" type="date" class="input"/></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">{{ busy?'Đang tạo...':'Tạo giải đấu' }}</button></div></form></BaseModal></div></template>
<style scoped>.filters{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px;padding:13px}.competition-card{min-height:285px}.top{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:20px}.competition-card h3{font-size:21px;margin:9px 0 6px}.metrics{display:grid;gap:8px;margin-top:20px;color:var(--muted);font-size:11px}.metrics span{display:flex;align-items:center;gap:7px}.bottom{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:13px;margin-top:18px;font-size:10px;color:var(--muted)}.actions{display:flex;justify-content:flex-end;gap:9px}.world-cup-preset{display:grid;gap:5px;padding:14px;border:1px solid rgba(255,204,82,.25);border-radius:13px;background:linear-gradient(135deg,rgba(255,210,86,.1),rgba(66,109,255,.08))}.world-cup-preset b{color:var(--yellow)}.world-cup-preset span{color:var(--muted);font-size:11px}.world-cup-card{border-color:rgba(255,204,82,.28);background:radial-gradient(circle at 90% 5%,rgba(255,204,82,.14),transparent 30%),linear-gradient(145deg,var(--panel),rgba(8,20,44,.82))}.world-cup-card:hover{box-shadow:0 28px 80px rgba(255,196,70,.14)}@media(max-width:700px){.filters{grid-template-columns:1fr}}</style>
